/* kstenerud/Musashi 68000 benchmark glue for the CpuEmulator comparative suite (the 68000
 * head-to-head C reference — mirrors z80c_runner.c for the Z80 / fake6502_runner.c for the 6502).
 *
 * Targets kstenerud/Musashi (the fast native C Motorola 680x0 interpreter used by MAME-class
 * projects, MIT). The host provides big-endian read/write callbacks over a 16 MiB 68000 board; the
 * core exposes m68k_init(), m68k_set_cpu_type(), m68k_pulse_reset(), m68k_set_reg(), and
 * m68k_execute(n) (runs >= n cycles, returns the cycles consumed). We drive m68k_execute(1) in a
 * loop so each call retires (at least) one instruction; we accumulate cycles AND count instructions.
 *
 * The Musashi sources (m68k*.c/.h, m68k_in.c, softfloat/) are fetched by bench/third-party/
 * fetch-subjects (NOT vendored — the fake6502.c / z80.c discipline). m68kops.h/m68kops.c are NOT
 * fetched — they are GENERATED by Musashi's own m68kmake codegen tool (the C# MusashiAdapter runs
 * that step, compile-once-cached). The mamesf.h shim (committed beside this file in
 * bench/third-party/) satisfies softfloat/milieu.h's unconditional #include "mamesf.h" (the FPU is
 * dead code here — our 68000-integer benchmark never executes an FP op — it just needs to link).
 *
 * Build (done by the C# adapter via the detected cc, after the m68kmake codegen step):
 *     cc -O2 -I<glueDir> -I<cache>/musashi -o musashi_runner musashi_runner.c \
 *        <cache>/musashi/m68kcpu.c <cache>/musashi/m68kops.c <cache>/musashi/m68kdasm.c \
 *        <cache>/musashi/softfloat/softfloat.c
 *
 * Usage: musashi_runner <image.bin> <startPc> <mode> <trapPc> <measureCycles>
 *   The CLI contract is IDENTICAL to z80c_runner (SubprocessRunner passes positional args). The 68000
 *   workloads use mode "cap"; they set UsesCpmBdos:false, so the bdos/trapPc args are accepted + IGNORED
 *   here (the 68000 terminates on the bounded window, not a CP/M BDOS CALL or a PC trap).
 *
 *   <measureCycles> is the bounded-window budget. The 68000 baseline LEADS with instructions/sec (its
 *   cycle axis is partial on `main`); to make the head-to-head instructions/sec directly comparable to
 *   our tiers' frozen INSTRUCTION caps, we treat <measureCycles> as the INSTRUCTION budget for the
 *   measured window — i.e. we run until instruction_count >= measureCycles (or, defensively, until the
 *   accumulated emulated cycles >= a generous multiple, so a degenerate stream still terminates). The
 *   reported CYCLES line still carries Musashi's own emulated-cycle count over that window.
 *
 * Prints THREE machine-readable lines the C# SubprocessRunner parses (CYCLES + WALL_SECONDS as the
 * z80c/6502 contract, PLUS an INSTRUCTIONS line so the head-to-head row carries guest-MIPS):
 *     CYCLES <n>
 *     INSTRUCTIONS <n>
 *     WALL_SECONDS <f>
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#ifdef _WIN32
#include <windows.h>
static double now_seconds(void) {
    LARGE_INTEGER f, c;
    QueryPerformanceFrequency(&f);
    QueryPerformanceCounter(&c);
    return (double)c.QuadPart / (double)f.QuadPart;
}
#else
static double now_seconds(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}
#endif

#include "m68k.h"

/* The 68000 board: a flat 16 MiB (R4 — the M68000TierDriver's board). The 68000 has a 24-bit address
 * bus, so every access is masked to 0xFFFFFF. */
#define MEM_SIZE 0x1000000
#define ADDR_MASK 0xFFFFFFu
static uint8_t mem[MEM_SIZE];

/* ── Musashi host memory callbacks (these names are MANDATORY — Musashi calls them directly). ──
 * The 68000 is BIG-ENDIAN: a 16-bit access is high byte first; a 32-bit access is four bytes,
 * most-significant first. */
unsigned int m68k_read_memory_8(unsigned int address) {
    return mem[address & ADDR_MASK];
}
unsigned int m68k_read_memory_16(unsigned int address) {
    unsigned int a = address & ADDR_MASK;
    return ((unsigned int)mem[a] << 8) | mem[(a + 1) & ADDR_MASK];
}
unsigned int m68k_read_memory_32(unsigned int address) {
    unsigned int a = address & ADDR_MASK;
    return ((unsigned int)mem[a] << 24)
         | ((unsigned int)mem[(a + 1) & ADDR_MASK] << 16)
         | ((unsigned int)mem[(a + 2) & ADDR_MASK] << 8)
         |  (unsigned int)mem[(a + 3) & ADDR_MASK];
}
void m68k_write_memory_8(unsigned int address, unsigned int value) {
    mem[address & ADDR_MASK] = (uint8_t)value;
}
void m68k_write_memory_16(unsigned int address, unsigned int value) {
    unsigned int a = address & ADDR_MASK;
    mem[a] = (uint8_t)(value >> 8);
    mem[(a + 1) & ADDR_MASK] = (uint8_t)value;
}
void m68k_write_memory_32(unsigned int address, unsigned int value) {
    unsigned int a = address & ADDR_MASK;
    mem[a] = (uint8_t)(value >> 24);
    mem[(a + 1) & ADDR_MASK] = (uint8_t)(value >> 16);
    mem[(a + 2) & ADDR_MASK] = (uint8_t)(value >> 8);
    mem[(a + 3) & ADDR_MASK] = (uint8_t)value;
}

/* The disassembler translation unit (m68kdasm.c) links against these — delegate to the read fns. */
unsigned int m68k_read_disassembler_8(unsigned int address)  { return m68k_read_memory_8(address); }
unsigned int m68k_read_disassembler_16(unsigned int address) { return m68k_read_memory_16(address); }
unsigned int m68k_read_disassembler_32(unsigned int address) { return m68k_read_memory_32(address); }

/* Reset the CPU to the workload's entry state. Mirrors the M68000TierDriver's SR=0x2700 (supervisor,
 * interrupts masked) + SSP=0x00FFFC; PC is the load/start address. */
static void setup(unsigned int start_pc) {
    m68k_init();
    m68k_set_cpu_type(M68K_CPU_TYPE_68000);
    m68k_pulse_reset();
    m68k_set_reg(M68K_REG_PC, start_pc);
    m68k_set_reg(M68K_REG_SR, 0x2700);
    m68k_set_reg(M68K_REG_SP, 0x00FFFC);
}

/* Run a bounded window driven by INSTRUCTIONS (the 68000's trustworthy comparable axis). Each
 * m68k_execute(1) retires at least one instruction and returns the cycles it consumed; we accumulate
 * both. The window closes when instr_count >= instr_budget (the primary, instruction-bounded
 * condition, so guest-MIPS is directly comparable to our tiers' frozen instruction caps), OR
 * defensively when cycles >= a generous cap (so a degenerate/stalled stream can never spin forever).
 * Returns the cycles consumed; *out_instructions receives the instruction count. */
static uint64_t run_window(uint64_t instr_budget, uint64_t *out_instructions) {
    uint64_t cycles = 0;
    uint64_t instrs = 0;
    /* A defensive cycle ceiling: the worst realistic cycles/instruction on the 68000 is well under
     * ~70, so 128x the instruction budget can never be reached by a healthy stream — it only guards a
     * pathological stall. */
    uint64_t cycle_ceiling = instr_budget * 128u;
    while (instrs < instr_budget) {
        int c = m68k_execute(1);
        if (c <= 0) c = 1;            /* never advance zero — guarantees forward progress */
        cycles += (uint64_t)c;
        instrs += 1;
        if (cycles >= cycle_ceiling) break;
    }
    *out_instructions = instrs;
    return cycles;
}

int main(int argc, char **argv) {
    if (argc != 6) {
        fprintf(stderr, "usage: %s <image.bin> <startPc> <mode> <trapPc> <measureCycles>\n", argv[0]);
        return 1;
    }
    const char *image_path = argv[1];
    unsigned int start_pc = (unsigned int)strtoul(argv[2], NULL, 10);
    /* argv[3] = mode ("cap" for the 68000), argv[4] = trapPc — both accepted + IGNORED here (the
     * 68000 workloads set UsesCpmBdos:false and terminate on the bounded window, not a BDOS/PC trap). */
    (void)argv[3];
    (void)argv[4];
    uint64_t measure = strtoull(argv[5], NULL, 10);

    /* The 68000 bench images are SMALL (a few KiB) and load at the workload's load address (0x1000),
     * NOT a flat 64 KiB like the Z80. Read the WHOLE file (its size is the image length) into mem at
     * start_pc. */
    FILE *f = fopen(image_path, "rb");
    if (!f) { perror("fopen"); return 1; }
    if (fseek(f, 0, SEEK_END) != 0) { fprintf(stderr, "fseek failed\n"); fclose(f); return 1; }
    long fsz = ftell(f);
    if (fsz < 0) { fprintf(stderr, "ftell failed\n"); fclose(f); return 1; }
    rewind(f);
    if ((unsigned long)fsz > (unsigned long)(MEM_SIZE - start_pc)) {
        fprintf(stderr, "image (%ld bytes) does not fit at 0x%X in the 16 MiB board\n", fsz, start_pc);
        fclose(f);
        return 1;
    }
    size_t image_len = (size_t)fsz;
    memset(mem, 0, MEM_SIZE);
    size_t n = fread(mem + start_pc, 1, image_len, f);
    fclose(f);
    if (n != image_len) { fprintf(stderr, "short read: %zu of %zu bytes\n", n, image_len); return 1; }

    /* Keep a pristine copy of the loaded image bytes so we can restore the board between the warmup
     * and measured passes (the sieve self-modifies its flag array at 0x2000). */
    uint8_t *image_copy = (uint8_t *)malloc(image_len);
    if (!image_copy) { fprintf(stderr, "out of memory\n"); return 1; }
    memcpy(image_copy, mem + start_pc, image_len);

    /* The instruction budget is <measureCycles> (we treat the window as instruction-bounded — see the
     * file header). Warmup uses a small slice (excluded), then the measured pass runs the full window. */
    uint64_t instr_budget = measure;
    uint64_t warm = instr_budget < 200000 ? instr_budget : 200000;
    uint64_t scratch;

    /* Warmup (excluded). */
    setup(start_pc);
    run_window(warm, &scratch);

    /* Restore the board (warmup may have self-modified the flag array) for the measured pass. The
     * code+data region begins at start_pc; everything else (stack, flag array) is scratch we zeroed
     * and that the program re-initializes from its entry — so restoring the loaded image bytes is the
     * faithful re-arm. */
    memset(mem, 0, MEM_SIZE);
    memcpy(mem + start_pc, image_copy, image_len);

    setup(start_pc);
    uint64_t instructions = 0;
    double t0 = now_seconds();
    uint64_t cycles = run_window(instr_budget, &instructions);
    double wall = now_seconds() - t0;

    free(image_copy);

    printf("CYCLES %llu\n", (unsigned long long)cycles);
    printf("INSTRUCTIONS %llu\n", (unsigned long long)instructions);
    printf("WALL_SECONDS %.6f\n", wall);
    return 0;
}
